CREATE TABLE IF NOT EXISTS edu_members (
 id INTEGER PRIMARY KEY, room TEXT NOT NULL, role TEXT NOT NULL, name TEXT NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, UNIQUE(room,role,name)
);
CREATE TABLE IF NOT EXISTS edu_sessions(token TEXT PRIMARY KEY, member INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS edu_tasks(id INTEGER PRIMARY KEY, room TEXT NOT NULL,title TEXT,body TEXT,kind TEXT,source TEXT,options TEXT,correct INTEGER);
CREATE TABLE IF NOT EXISTS edu_work(id INTEGER PRIMARY KEY, student INTEGER,task INTEGER,answer TEXT,declared INTEGER,scores TEXT,note TEXT,approved INTEGER DEFAULT 0, UNIQUE(student,task));
CREATE TABLE IF NOT EXISTS edu_books(id TEXT PRIMARY KEY,room TEXT,title TEXT,kind TEXT,ext TEXT,count INTEGER);
CREATE TABLE IF NOT EXISTS edu_parts(book TEXT,idx INTEGER,body TEXT,PRIMARY KEY(book,idx));
CREATE TABLE IF NOT EXISTS edu_pages(book TEXT,page INTEGER,body TEXT,PRIMARY KEY(book,page));
CREATE TABLE IF NOT EXISTS edu_meet(id INTEGER PRIMARY KEY,room TEXT,title TEXT,call TEXT,minutes INTEGER,prompt TEXT,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS edu_visit(meeting INTEGER,student INTEGER,seconds REAL DEFAULT 0,last REAL DEFAULT 0,response TEXT DEFAULT '',score INTEGER,note TEXT DEFAULT '',PRIMARY KEY(meeting,student));
CREATE TABLE IF NOT EXISTS edu_quota(member INTEGER,bucket INTEGER,count INTEGER,PRIMARY KEY(member,bucket));
